# Launch/operations observability page.
sap_file_health <- function(paths) data.frame(component=paths, status=ifelse(file.exists(paths),"Ready","Missing"), stringsAsFactors=FALSE)
mod_operations_center_ui<-function(id){ns<-NS(id);tagList(sap_professional_header("Operations Center","Deployment health, package integrity and production-readiness checks for administrators.","tower-broadcast","Launch operations"),uiOutput(ns("health_cards")),layout_columns(card(card_header("Critical assets"),DT::DTOutput(ns("assets"))),card(card_header("Runtime guidance"),tags$ul(tags$li("Run INSTALL_DEPENDENCIES.R once on a clean environment."),tags$li("Run CHECK_APP.R before every release."),tags$li("Use PostgreSQL for durable multi-instance production."),tags$li("Keep .env, .Renviron and account databases outside deployment bundles."),tags$li("Back up the database and test restore procedures."))),col_widths=c(7,5)))}
mod_operations_center_server<-function(id,app_state,services=NULL) moduleServer(id,function(input,output,session){assets<-reactive(sap_file_health(c("app.R","CHECK_APP.R","INSTALL_DEPENDENCIES.R","RUN_APP.R","deploy_shinyapps.R","VERSION","DESCRIPTION","www/sap-professional-suite.css","www/sap-professional-suite.js","docs/USER_GUIDE.md","docs/PRODUCTION_CHECKLIST.md")));output$assets<-DT::renderDT(DT::datatable(assets(),options=list(dom='t'),rownames=FALSE));output$health_cards<-renderUI({a<-assets();div(class="sap-pro-kpi-grid",sap_pro_kpi("Release",SAP_VERSION,SAP_RELEASE_NAME,"tag"),sap_pro_kpi("Runtime",SAP_RUNTIME_LABEL,"active profile","server"),sap_pro_kpi("Critical assets",sum(a$status=="Ready"),paste("of",nrow(a),"ready"),"folder-check","success"),sap_pro_kpi("Database",if(SAP_POSTGRES_ENABLED)"Connected" else "Standalone",if(SAP_POSTGRES_ENABLED)"PostgreSQL" else "local account mode","database",if(SAP_POSTGRES_ENABLED)"success" else "warning"))})})
